table inet alma_portal_sip {
	set agents4 {
		type ipv4_addr
		flags timeout
		elements = { 158.62.74.253 timeout 35s expires 25s80ms }
	}

	set grace4 {
		type ipv4_addr
		flags timeout
		elements = { 158.62.74.253 timeout 2m35s expires 2m25s80ms }
	}

	chain input {
		type filter hook input priority filter - 10; policy accept;
		iifname "lo" return
		udp dport 5060 ip saddr @agents4 return
		udp dport 5060 counter packets 11619 bytes 8654080 drop
		udp dport 5061 ip saddr @agents4 return
		udp dport 5061 counter packets 199 bytes 121356 drop
		udp dport 10000-20000 ip saddr @agents4 ct mark set ct mark | 0x40000000 return
		udp dport 10000-20000 ip saddr @grace4 ct state established ct mark & 0x40000000 != 0x00000000 return
		udp dport 10000-20000 counter packets 318 bytes 54620 drop comment "alma-phone-sip-5060-5061-v1"
	}

	chain output {
		type filter hook output priority filter - 10; policy accept;
		oifname "lo" return
		udp sport 5060 ip daddr @agents4 return
		udp sport 5060 counter packets 0 bytes 0 drop
		udp sport 5061 ip daddr @agents4 return
		udp sport 5061 counter packets 0 bytes 0 drop
		udp sport 10000-20000 ip daddr @agents4 ct mark set ct mark | 0x40000000 return
		udp sport 10000-20000 ip daddr @grace4 ct state established ct mark & 0x40000000 != 0x00000000 return
		udp sport 10000-20000 counter packets 49 bytes 3577 drop comment "alma-phone-sip-5060-5061-v1"
	}
}
